package com.sibcraft.creeperborn.client;

import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.model.geom.*;
import net.minecraft.client.model.geom.builders.*;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.entity.state.*;
import net.minecraft.client.renderer.rendertype.RenderTypes;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.resources.Identifier;
import org.joml.Quaternionf;

/** Articulated roots, jointed human limbs and two distinct giant bodies; biome textures are native block assets. */
public final class NatureRenderer {
    private static Identifier block(String s){return Identifier.withDefaultNamespace("textures/block/"+s+".png");}
    private static final String[] WOODS={"oak_log","spruce_log","birch_log","dark_oak_log","acacia_log","jungle_log","mangrove_log","cherry_log","bamboo_block","pale_oak_log","crimson_stem","warped_stem"};
    private static final Identifier SKIN=block("white_terracotta"),PINK=block("pink_concrete"),WHITE=block("white_concrete"),DARK=block("black_terracotta"),EYE=block("purple_concrete"),HAIR=block("black_concrete"),MEMBRANE=block("purple_terracotta");
    private static final ModelPart ROOT=root(),HAND=hand(),BRANCH=branch(),SPOKES=spokes(),ARM=arm(),FOOT=foot(),TREE=tree(),LEAF=leaves(),DEMON=demon(),DRESS=dress(),FACE=face(),EYES=eyes(),PUPILS=pupils(),WINGS=wings(),BONES=wingBones(),FLOWER=flower(),STEM=stem(),BLOOM=bloom(),NET=net();
    private static void box(PartDefinition p,String name,float x,float y,float z,float w,float h,float d){p.addOrReplaceChild(name,CubeListBuilder.create().texOffs(0,0).addBox(x,y,z,w,h,d),PartPose.ZERO);}
    private static ModelPart bake(MeshDefinition m){return LayerDefinition.create(m,16,16).bakeRoot();}
    private static ModelPart root(){MeshDefinition m=new MeshDefinition();var p=m.getRoot();for(int i=0;i<9;i++){float width=3.5f-i*.32f;var next=p.addOrReplaceChild("joint"+i,CubeListBuilder.create(),PartPose.offset(0,0,i==0?0:1.8f));box(next,"wood",-width/2,-width/2,0,width,width,2.2f);p=next;}return bake(m);}
    private static ModelPart hand(){MeshDefinition m=new MeshDefinition();var p=m.getRoot();box(p,"palm",-2,-.7f,-1,4,1.4f,3.5f);for(int i=0;i<4;i++){var finger=p.addOrReplaceChild("finger"+i,CubeListBuilder.create(),PartPose.offset(-1.6f+i,0,2.3f));box(finger,"base",-.4f,-.55f,0,.8f,1.1f,2);var tip=finger.addOrReplaceChild("tip",CubeListBuilder.create(),PartPose.offset(0,0,1.8f));box(tip,"bone",-.35f,-.5f,0,.7f,1,1.5f);}box(p,"thumb",1.8f,-.5f,-.2f,1,1,2);return bake(m);}
    private static ModelPart branch(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"forearm",-6,-6,-16,12,12,11);box(r,"fist",-8,-8,-6,16,16,12);for(int i=0;i<4;i++)box(r,"knuckle"+i,-8+i*4,-7,5,3.7f,14,3);return bake(m);}
    private static ModelPart spokes(){MeshDefinition m=new MeshDefinition();box(m.getRoot(),"stems",-17,-.4f,-.4f,34,.8f,.8f);return bake(m);}
    private static ModelPart arm(){MeshDefinition m=new MeshDefinition();var p=m.getRoot();box(p,"upper",-1.3f,-1.3f,0,2.6f,2.6f,7);var elbow=p.addOrReplaceChild("elbow",CubeListBuilder.create(),PartPose.offset(0,0,6.5f));box(elbow,"forearm",-1.1f,-1.1f,0,2.2f,2.2f,7);return bake(m);}
    private static ModelPart foot(){MeshDefinition m=new MeshDefinition();var p=m.getRoot();box(p,"shin",-2,0,-2,4,13,4);box(p,"foot",-2.5f,0,-3,5,3,8);for(int i=0;i<5;i++)box(p,"toe"+i,-2.5f+i,.3f,4.7f,.9f,1.8f,1.8f);return bake(m);}
    private static ModelPart tree(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"trunk",-7,16,-4,14,27,8);box(r,"head",-5,43,-4,10,12,8);box(r,"jaw",-4,42,2,8,3,4);for(int side:new int[]{-1,1}){var a=r.addOrReplaceChild("arm"+side,CubeListBuilder.create(),PartPose.offset(side*9,39,0));box(a,"upper",-3,-15,-3,6,17,6);var fore=a.addOrReplaceChild("fore",CubeListBuilder.create(),PartPose.offset(0,-14,0));box(fore,"wood",-3.5f,-14,-3.5f,7,15,7);for(int i=0;i<4;i++)box(fore,"finger"+i,-3.1f+i*1.7f,-18,0,1.4f,5,3);var leg=r.addOrReplaceChild("leg"+side,CubeListBuilder.create(),PartPose.offset(side*4,18,0));box(leg,"wood",-3.5f,-16,-3.5f,7,18,7);box(leg,"roots",-5,-18,-5,10,4,13);}return bake(m);}
    private static ModelPart leaves(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int i=0;i<7;i++){double a=i*Math.PI*2/7;box(r,"crown"+i,(float)Math.cos(a)*7-5,51+i%3*2,(float)Math.sin(a)*5-4,10,5,8);}for(int side:new int[]{-1,1})box(r,"shoulder"+side,side*10-5,37,-4,10,6,8);return bake(m);}
    private static ModelPart demon(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"waist",-3.5f,17,-2,7,8,4);box(r,"chest",-5,25,-2.5f,10,8,5);box(r,"neck",-1.5f,32,-1.4f,3,3,2.8f);box(r,"head",-3.5f,35,-3,7,8,6);for(int side:new int[]{-1,1}){var leg=r.addOrReplaceChild("leg"+side,CubeListBuilder.create(),PartPose.offset(side*2.6f,18,0));box(leg,"thigh",-1.8f,-9,-1.8f,3.6f,9,3.6f);box(leg,"calf",-1.4f,-17,-1.4f,2.8f,9,2.8f);box(leg,"foot",-1.5f,-18,-1.7f,3,2,5);}return bake(m);}
    private static ModelPart dress(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"bodice",-3.8f,18,-2.4f,7.6f,9,4.8f);box(r,"bust",-5.2f,26,-2.7f,10.4f,4,5.8f);box(r,"hips",-5.3f,13,-3,10.6f,6,6);for(int side:new int[]{-1,1}){var panel=r.addOrReplaceChild("panel"+side,CubeListBuilder.create(),PartPose.offsetAndRotation(side*3.5f,16,-1,0,0,side*.15f));box(panel,"cloth",-2,-9,-2,4,10,4);box(r,"horn"+side+"0",side*3-.7f,42,-1,1.4f,4,1.4f);box(r,"horn"+side+"1",side*3.5f-.6f,45,-1,1.2f,3,1.2f);}return bake(m);}
    private static ModelPart face(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"hair",-4,37,-3.6f,8,7,3);box(r,"fringe",-3.8f,41,2.5f,7.6f,2,1);for(int side:new int[]{-1,1})box(r,"lock"+side,side*3.6f-.7f,30,-2.8f,1.4f,12,4.5f);return bake(m);}
    private static ModelPart eyes(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1})box(r,"eye"+side,side*1.6f-.8f,38.6f,3.02f,1.6f,.8f,.15f);return bake(m);}
    private static ModelPart pupils(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1})box(r,"iris"+side,side*1.6f-.3f,38.6f,3.2f,.6f,.8f,.1f);box(r,"mouth",-.8f,36.7f,3.05f,1.6f,.3f,.12f);return bake(m);}
    private static ModelPart wings(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1}){var wing=r.addOrReplaceChild("wing"+side,CubeListBuilder.create(),PartPose.offset(side*4,27,-4));for(int i=0;i<7;i++){float x=i*2.8f;float top=3.5f-i*.45f;float bottom=-3-(float)Math.sin(i*Math.PI/3)*1.7f-i*.55f;box(wing,"membrane"+i,side>0?x:-x-3,bottom,-.4f,3,top-bottom,.8f);}}return bake(m);}
    private static ModelPart wingBones(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int side:new int[]{-1,1}){var wing=r.addOrReplaceChild("wing"+side,CubeListBuilder.create(),PartPose.offset(side*4,27,-4));for(int i=0;i<7;i++)box(wing,"rim"+i,side>0?i*2.8f:-i*2.8f-3,3.1f-i*.45f,-.6f,3,.9f,1.2f);for(int i=1;i<=3;i++)box(wing,"rib"+i,side*(i*5.5f)-.35f,-4-i*.6f,-.65f,.7f,7.5f,1.3f);}return bake(m);}
    private static ModelPart stem(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"attachment",-1,12,-4.1f,2,2,5);box(r,"stalk",-.55f,12,-4.1f,1.1f,21,1.1f);box(r,"leaf",-.5f,16,-4,5,1,3);return bake(m);}
    private static ModelPart bloom(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"flower",-8,-8,0,16,16,0);return bake(m);}
    private static Identifier flowerTexture(int palette){return block(palette==7?"pink_tulip":palette==10?"poppy":palette==11?"cornflower":palette==2?"allium":"oxeye_daisy");}
    public static void followOwner(net.minecraft.world.entity.Display.BlockDisplay d,BlockDisplayEntityRenderState state,float partial){if(d.getCustomName()==null||kind(d.getCustomName().getString())!=3)return;try{var c=net.minecraft.client.Minecraft.getInstance();var owner=c.level==null?null:c.level.getPlayerByUUID(java.util.UUID.fromString(d.getCustomName().getString().split("\\|",3)[2]));if(owner!=null){var at=owner.getPosition(partial);state.x=at.x;state.y=at.y;state.z=at.z;}}catch(IllegalArgumentException ignored){}}
    private static ModelPart flower(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();box(r,"stem",-1,-4,-1,2,10,2);box(r,"core",-3,5,-3,6,2,6);for(int i=0;i<8;i++){double a=i*Math.PI/4;var p=r.addOrReplaceChild("petal"+i,CubeListBuilder.create(),PartPose.offsetAndRotation((float)Math.cos(a)*5,6,(float)Math.sin(a)*5,0,(float)-a,0));box(p,"flower",-1,-.6f,-2,8,1.2f,4);}return bake(m);}
    private static ModelPart net(){MeshDefinition m=new MeshDefinition();var r=m.getRoot();for(int spoke=0;spoke<8;spoke++){var a=r.addOrReplaceChild("spoke"+spoke,CubeListBuilder.create(),PartPose.rotation(0,(float)(spoke*Math.PI/4),0));for(int i=0;i<5;i++){box(a,"arm"+i,-.35f,(i%2)*.12f,i*2.8f,.7f,.6f,3.3f);box(a,"hand"+i,-.5f,0,i*2.8f+2,.95f,.7f,1);}}for(int ring=1;ring<=3;ring++)for(int i=0;i<24;i++){double a=i*Math.PI/12;var p=r.addOrReplaceChild("ring"+ring+"_"+i,CubeListBuilder.create(),PartPose.offsetAndRotation((float)Math.cos(a)*ring*4.2f,0,(float)Math.sin(a)*ring*4.2f,0,(float)(-a+Math.PI/2),0));box(p,"linked",-.4f,-.3f,-.2f,.8f,.6f,1.3f);}return bake(m);}
    public static int kind(String name){if(!name.startsWith("cb_nature_"))return 0;try{int k=Integer.parseInt(name.substring(10,name.indexOf('|')));return k>=1&&k<=14?k:0;}catch(RuntimeException ignored){return 0;}}
    public static int palette(String name){try{return Math.max(0,Math.min(11,Integer.parseInt(name.split("\\|",3)[1])));}catch(RuntimeException ignored){return 0;}}
    private static void draw(ModelPart m,Identifier texture,PoseStack p,SubmitNodeCollector n,boolean glow){n.submitModelPart(m,p,glow?RenderTypes.eyes(texture):RenderTypes.entityTranslucent(texture),0xF000F0,OverlayTexture.NO_OVERLAY,null);}
    private static void root(PoseStack p,SubmitNodeCollector n,int palette,float age,float bend){var part=ROOT;for(int i=0;i<9;i++){part=part.getChild("joint"+i);part.xRot=(float)Math.sin(age*.2-i*.45)*bend;part.yRot=(float)Math.cos(age*.14-i*.3)*bend*.7f;}draw(ROOT,block(WOODS[Math.max(0,Math.min(11,palette))]),p,n,false);}
    private static void limb(PoseStack p,SubmitNodeCollector n,float age,float curl,boolean dark){ARM.getChild("elbow").xRot=curl;draw(ARM,dark?DARK:SKIN,p,n,false);p.pushPose();p.translate(0,-Math.sin(curl)*7/16, (6.5+Math.cos(curl)*7)/16);for(int i=0;i<4;i++)HAND.getChild("finger"+i).getChild("tip").xRot=-.8f*Math.max(0,curl);draw(HAND,dark?DARK:SKIN,p,n,false);p.popPose();}
    public static void submit(int kind,int palette,float age,PoseStack p,SubmitNodeCollector n){p.pushPose();
        if((kind==1||kind==2)&&age>82){p.popPose();return;}
        if(kind==1||kind==2){if(kind==2){draw(BRANCH,block(WOODS[palette]),p,n,false);}else root(p,n,palette,age,.13f);}
        else if(kind==3){for(int i=0;i<6;i++){p.pushPose();p.rotate(new Quaternionf().rotationY(age*.22f+i*(float)Math.PI/3));p.translate(0,.5,0);p.scale(.35f,.5f,1);root(p,n,palette,age,.2f);p.popPose();}}
        else if(kind==4||kind==11){for(int i=0;i<6;i++){double a=i*Math.PI/3;p.pushPose();p.translate(Math.cos(a)*.35,.15+i*.12,Math.sin(a)*.35);p.rotate(new Quaternionf().rotationY((float)(-a-Math.PI/2)));p.scale(.6f,.6f,.6f);if(kind==4)root(p,n,palette,age,.23f);else limb(p,n,age,.6f+Math.min(1,age/20)*.8f,false);p.popPose();}}
        else if(kind==5){for(int i=0;i<3;i++){p.pushPose();p.rotate(new Quaternionf().rotationY(i*2.1f));p.scale(.3f,.3f,.7f);root(p,n,palette,age,.2f);p.popPose();}}
        else if(kind==12){p.translate(0,Math.max(0,1-age/12)*2,0);draw(FOOT,SKIN,p,n,false);}
        else if(kind==13){int chains=Math.max(1,Math.min(5,palette));for(int chain=0;chain<chains;chain++)for(int i=0;i<10;i++){double a=chain*Math.PI*2/chains;p.pushPose();p.translate((chains==1?0:Math.cos(a)*.3)+Math.sin(i*.4+age*.07)*.04,chains==1?0:Math.sin(a)*.3,i/10f);p.scale(.3f,.3f,.1f);limb(p,n,age,.1f,false);p.popPose();}}
        else if(kind==14){float open=Math.min(1,age/6);p.scale(open,1,open);draw(NET,SKIN,p,n,false);}
        p.popPose();}
    public static void avatar(AvatarRenderState s,PoseStack p,SubmitNodeCollector n,int flags,boolean overlay){boolean tree=(flags&3)==1,giant=(flags&4)!=0;int palette=(flags>>6)&15;palette=Math.min(11,palette);float age=s.ageInTicks;
        p.pushPose();p.rotate(new Quaternionf().rotationY((float)Math.toRadians(-s.bodyRot)));
        if(giant&&!overlay){float size=tree?((flags&1024)!=0?1.6f:1):1.3f;p.scale(size,size,size);if(tree){for(int side:new int[]{-1,1}){TREE.getChild("arm"+side).xRot=(float)Math.sin(age*.12+side)*.25f;TREE.getChild("arm"+side).getChild("fore").zRot=(float)Math.sin(age*.1+side)*.08f;TREE.getChild("leg"+side).xRot=(float)Math.sin(age*.15+side)*.12f;}draw(TREE,block(WOODS[palette]),p,n,false);draw(LEAF,block(palette==7?"cherry_leaves":palette==9?"pale_moss_block":palette==10?"nether_wart_block":palette==11?"warped_wart_block":"moss_block"),p,n,false);}else{for(int side:new int[]{-1,1}){DEMON.getChild("leg"+side).xRot=(float)Math.sin(age*.1+side)*.08f;float flap=side*(.25f+(float)Math.sin(age*.13)*.16f);WINGS.getChild("wing"+side).yRot=flap;BONES.getChild("wing"+side).yRot=flap;for(int arm=0;arm<3;arm++){p.pushPose();p.translate(side*(.27+arm*.04),1.83-arm*.23,-arm*.06);p.rotate(new Quaternionf().rotationYXZ(side*(.5f+arm*.35f),.95f-arm*.17f,side*.15f));p.scale(1.05f,1.05f,1.05f);limb(p,n,age,.55f+(float)Math.sin(age*.08+arm)*.12f,false);p.popPose();}}draw(DEMON,SKIN,p,n,false);draw(DRESS,HAIR,p,n,false);draw(FACE,HAIR,p,n,false);draw(WINGS,MEMBRANE,p,n,false);draw(BONES,HAIR,p,n,false);draw(EYES,WHITE,p,n,false);draw(PUPILS,EYE,p,n,false);}}

        if(overlay&&tree&&(flags&8)!=0){draw(STEM,block("green_concrete"),p,n,false);p.pushPose();p.translate(0,33/16.0,-3.55/16.0);p.rotate(new Quaternionf().rotationY(age*.35f));draw(SPOKES,block("green_concrete"),p,n,false);for(int flower=0;flower<3;flower++){p.pushPose();p.translate(flower==0?0:flower==1?-1.05:1.05,0,0);p.rotate(new Quaternionf().rotationX((float)Math.PI/2));float size=flower==0?1.7f:.85f;p.scale(size,size,size);n.submitModelPart(BLOOM,p,RenderTypes.entityTranslucent(block(flower==0?"sunflower_front":"cornflower")),0xF000F0,OverlayTexture.NO_OVERLAY,null);p.popPose();}p.popPose();}

        if(overlay&&(flags&32)!=0){for(int i=0;i<5;i++){p.pushPose();double a=age*.1+i*Math.PI*2/5;p.translate(Math.cos(a)*.5,.4+i*.25,Math.sin(a)*.5);p.scale(.2f,.2f,.2f);draw(FLOWER,PINK,p,n,false);p.popPose();}}
        p.popPose();}
    public static java.util.List<Identifier> textures(){var list=new java.util.ArrayList<Identifier>();for(String wood:WOODS)list.add(block(wood));for(String leaf:new String[]{"sunflower_front","oxeye_daisy","pink_tulip","poppy","cornflower","allium","green_concrete","moss_block","cherry_leaves","pale_moss_block","nether_wart_block","warped_wart_block"})list.add(block(leaf));return list;}
    public static void validate(){TREE.getChild("arm1").getChild("fore");DRESS.getChild("horn10");if(WINGS.getChild("wing1").y>=34||WINGS.getChild("wing1").z>=-3)throw new AssertionError("Wings must attach below head behind torso");NET.getChild("spoke7");HAND.getChild("finger3").getChild("tip");if(kind("cb_nature_14|0|owner")!=14||kind("bad")!=0||palette("cb_nature_1|99|owner")!=11)throw new AssertionError("Nature metadata validation");}
}
